/**
 * storage.js
 * لایه مدیریت داده‌ها — اکنون به‌جای LocalStorage، مستقیماً با Supabase (PostgreSQL ابری) کار می‌کند.
 * تمام داده‌های اصلی (واحدها، دریافت‌ها، هزینه‌ها، شارژها، اشخاص، تنظیمات) در Supabase ذخیره می‌شوند.
 * برای سرعت و سادگی، یک نسخه در حافظه (کش) از تمام داده‌ها نگه‌داری می‌شود که در زمان بارگذاری برنامه
 * از Supabase خوانده می‌شود و با هر تغییر (افزودن/ویرایش/حذف) هم‌زمان با سرور به‌روزرسانی می‌گردد.
 *
 * تنها چیزی که هنوز به‌صورت محلی (در همان مرورگر) ذخیره می‌شود، اطلاعات "اتصال" است:
 * آدرس پروژه Supabase و کلید anon - چون این‌ها مشخصات اتصال هستند، نه داده‌های ساختمان.
 */

const SUPABASE_CONFIG_KEY = 'bcm_supabase_config';
const DATA_CACHE_KEY = 'bcm_data_cache';

/** اطلاعات پیش‌فرض اتصال به پروژه Supabase - جاسازی‌شده در خود برنامه
 *  تا نیازی به وارد کردن دستی در هر دستگاه/مرورگر نباشد. */
const DEFAULT_SUPABASE_CONFIG = {
  url: 'https://digdsbzgxjpqqqasvtoi.supabase.co',
  anonKey: 'sb_publishable_BLpxwdOmIwDqeAd0Q6JCfA_BvKs0jWQ'
};

/** مدیریت تنظیمات اتصال به Supabase (پیش‌فرض جاسازی‌شده در برنامه؛ در صورت نیاز با مقدار محلی مرورگر بازنویسی می‌شود) */
const SupabaseConfig = (() => {
  function get() {
    try {
      const raw = localStorage.getItem(SUPABASE_CONFIG_KEY);
      const local = raw ? JSON.parse(raw) : null;
      if (local && local.url && local.anonKey) return local;
    } catch (e) { /* نادیده گرفته می‌شود و مقدار پیش‌فرض استفاده می‌شود */ }
    return DEFAULT_SUPABASE_CONFIG.url && DEFAULT_SUPABASE_CONFIG.anonKey ? DEFAULT_SUPABASE_CONFIG : null;
  }
  function save(url, anonKey) {
    localStorage.setItem(SUPABASE_CONFIG_KEY, JSON.stringify({ url: url.trim(), anonKey: anonKey.trim() }));
  }
  function clear() {
    localStorage.removeItem(SUPABASE_CONFIG_KEY);
  }
  function isConfigured() {
    const c = get();
    return !!(c && c.url && c.anonKey);
  }
  return { get, save, clear, isConfigured };
})();

/* =========================================================
 * نگاشت نام فیلدها بین جاوااسکریپت (camelCase) و Supabase (snake_case)
 * ========================================================= */
const FieldMap = {
  unit: {
    toDb: u => ({
      code: u.code || null, number: u.number, floor: u.floor || null, block: u.block || null,
      owner: u.owner || null, tenant: u.tenant || null, phone: u.phone || null,
      area: u.area || null, charge_share: u.chargeShare || 0, initial_debt: u.initialDebt || 0,
      status: u.status || 'active', description: u.description || null
    }),
    fromDb: r => ({
      id: r.id, code: r.code, number: r.number, floor: r.floor, block: r.block,
      owner: r.owner, tenant: r.tenant, phone: r.phone, area: r.area,
      chargeShare: r.charge_share, initialDebt: r.initial_debt,
      status: r.status, description: r.description, createdAt: r.created_at
    })
  },
  receipt: {
    toDb: r => ({
      doc_no: r.docNo || null, date: r.date, unit_id: r.unitId || null, type: r.type || null,
      description: r.description || null, amount: r.amount || 0, method: r.method || 'transfer',
      tracking_no: r.trackingNo || null, registrar: r.registrar || null, attachment: r.attachment || null
    }),
    fromDb: r => ({
      id: r.id, docNo: r.doc_no, date: r.date, unitId: r.unit_id, type: r.type,
      description: r.description, amount: r.amount, method: r.method,
      trackingNo: r.tracking_no, registrar: r.registrar, attachment: r.attachment, createdAt: r.created_at
    })
  },
  expense: {
    toDb: e => ({
      doc_no: e.docNo || null, date: e.date, category: e.category || null,
      description: e.description || null, amount: e.amount || 0, pay_to: e.payTo || null,
      invoice_no: e.invoiceNo || null, registrar: e.registrar || null, attachment: e.attachment || null,
      person_id: e.personId || null
    }),
    fromDb: r => ({
      id: r.id, docNo: r.doc_no, date: r.date, category: r.category,
      description: r.description, amount: r.amount, payTo: r.pay_to,
      invoiceNo: r.invoice_no, registrar: r.registrar, attachment: r.attachment,
      personId: r.person_id, createdAt: r.created_at
    })
  },
  charge: {
    toDb: c => ({
      doc_no: c.docNo || null, unit_id: c.unitId, jy: c.jy, jm: c.jm,
      date: c.date, amount: c.amount || 0, description: c.description || null
    }),
    fromDb: r => ({
      id: r.id, docNo: r.doc_no, unitId: r.unit_id, jy: r.jy, jm: r.jm,
      date: r.date, amount: r.amount, description: r.description, createdAt: r.created_at
    })
  },
  person: {
    toDb: p => ({
      name: p.name, type: p.type || null, phone: p.phone || null,
      national_id: p.nationalId || null, status: p.status || 'active', description: p.description || null
    }),
    fromDb: r => ({
      id: r.id, name: r.name, type: r.type, phone: r.phone,
      nationalId: r.national_id, status: r.status, description: r.description, createdAt: r.created_at
    })
  },
  settings: {
    toDb: s => ({
      building_name: s.buildingName || null, address: s.address || null, phone: s.phone || null,
      manager: s.manager || null, logo: s.logo || null, currency: s.currency || 'تومان',
      primary_color: s.primaryColor || '#2563eb', theme: s.theme || 'light', font: s.font || 'IRANSansX',
      auth_enabled: !!s.authEnabled, auth_username: s.authUsername || null,
      auth_password_hash: s.authPasswordHash || null, auth_timeout_minutes: s.authTimeoutMinutes || 15
    }),
    fromDb: r => ({
      buildingName: r.building_name, address: r.address, phone: r.phone, manager: r.manager,
      logo: r.logo, currency: r.currency, primaryColor: r.primary_color, theme: r.theme, font: r.font,
      authEnabled: !!r.auth_enabled, authUsername: r.auth_username,
      authPasswordHash: r.auth_password_hash, authTimeoutMinutes: r.auth_timeout_minutes || 15
    })
  }
};

const DEFAULT_SETTINGS = {
  buildingName: 'مجتمع رستورانی کشتی ایرانی', address: '', phone: '', manager: '',
  logo: 'data:image/png;base64,',
  currency: 'تومان', primaryColor: '#2563eb', theme: 'light', font: 'IRANSansX',
  authEnabled: false, authUsername: '', authPasswordHash: '', authTimeoutMinutes: 15
};

class StorageManager {
  constructor() {
    this.client = null;
    this.cache = { units: [], receipts: [], expenses: [], charges: [], persons: [], settings: null };
    this.ready = false;
  }

  /** بررسی می‌کند که آیا LocalStorage در این مرورگر/این آدرس قابل استفاده است یا خیر */
  static isStorageAvailable() {
    try {
      const testKey = '__bcm_test__';
      localStorage.setItem(testKey, '1');
      localStorage.removeItem(testKey);
      return true;
    } catch (e) {
      return false;
    }
  }

  /** بارگذاری فوری آخرین نسخه ذخیره‌شده داده‌ها از حافظه محلی (برای نمایش سریع صفحه، بدون انتظار برای شبکه) */
  loadCacheFromLocalStorage() {
    try {
      const raw = localStorage.getItem(DATA_CACHE_KEY);
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      if (!parsed || !Array.isArray(parsed.units)) return false;
      this.cache.units = parsed.units || [];
      this.cache.receipts = parsed.receipts || [];
      this.cache.expenses = parsed.expenses || [];
      this.cache.charges = parsed.charges || [];
      this.cache.persons = parsed.persons || [];
      this.cache.settings = parsed.settings || null;
      this.ready = true;
      return true;
    } catch (e) {
      console.warn('خواندن کش محلی ناموفق بود', e);
      return false;
    }
  }

  /** ذخیره نسخه فعلی کش در حافظه محلی، برای بارگذاری فوری در دفعه بعد */
  saveCacheToLocalStorage() {
    try {
      localStorage.setItem(DATA_CACHE_KEY, JSON.stringify({
        units: this.cache.units, receipts: this.cache.receipts, expenses: this.cache.expenses,
        charges: this.cache.charges, persons: this.cache.persons, settings: this.cache.settings,
        cachedAt: Date.now()
      }));
    } catch (e) {
      console.warn('ذخیره کش محلی ناموفق بود (احتمالاً حجم زیاد پیوست‌ها)', e);
    }
  }

  /** اتصال به Supabase و بارگذاری اولیه/به‌روزرسانی تمام داده‌ها در کش */
  async init() {
    const cfg = SupabaseConfig.get();
    if (!cfg) throw new Error('اطلاعات اتصال Supabase یافت نشد');
    if (!this.client) this.client = window.supabase.createClient(cfg.url, cfg.anonKey);

    const [unitsRes, receiptsRes, expensesRes, chargesRes, personsRes, settingsRes] = await Promise.all([
      this.client.from('units').select('*').order('created_at', { ascending: true }),
      this.client.from('receipts').select('*').order('created_at', { ascending: true }),
      this.client.from('expenses').select('*').order('created_at', { ascending: true }),
      this.client.from('charges').select('*').order('created_at', { ascending: true }),
      this.client.from('persons').select('*').order('created_at', { ascending: true }),
      this.client.from('settings').select('*').eq('id', 1).maybeSingle()
    ]);

    const firstError = unitsRes.error || receiptsRes.error || expensesRes.error || chargesRes.error || personsRes.error || settingsRes.error;
    if (firstError) throw firstError;

    this.cache.units = (unitsRes.data || []).map(FieldMap.unit.fromDb);
    this.cache.receipts = (receiptsRes.data || []).map(FieldMap.receipt.fromDb);
    this.cache.expenses = (expensesRes.data || []).map(FieldMap.expense.fromDb);
    this.cache.charges = (chargesRes.data || []).map(FieldMap.charge.fromDb);
    this.cache.persons = (personsRes.data || []).map(FieldMap.person.fromDb);

    if (settingsRes.data) {
      this.cache.settings = FieldMap.settings.fromDb(settingsRes.data);
      // اگر ردیف تنظیمات از قبل (مثلاً توسط اسکریپت SQL) بدون لوگو ساخته شده، لوگوی پیش‌فرض را اضافه کن
      if (!this.cache.settings.logo && DEFAULT_SETTINGS.logo) {
        await this.saveSettings({ logo: DEFAULT_SETTINGS.logo });
      }
    } else {
      // اولین اجرا: هیچ ردیف تنظیماتی وجود ندارد، پس مقادیر پیش‌فرض را می‌سازیم
      const insertRes = await this.client.from('settings').insert({ id: 1, ...FieldMap.settings.toDb(DEFAULT_SETTINGS) }).select().maybeSingle();
      this.cache.settings = insertRes.data ? FieldMap.settings.fromDb(insertRes.data) : { ...DEFAULT_SETTINGS };
    }

    this.ready = true;
    this.saveCacheToLocalStorage();
  }

  /* ------------------ واحدها ------------------ */
  getUnits() { return this.cache.units; }
  getUnitById(id) { return this.cache.units.find(u => u.id === id); }

  async addUnit(unit) {
    const { data, error } = await this.client.from('units').insert(FieldMap.unit.toDb(unit)).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ذخیره‌سازی روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.units.push(FieldMap.unit.fromDb(data));
    this.saveCacheToLocalStorage();
    return true;
  }
  async updateUnit(id, patch) {
    const { data, error } = await this.client.from('units').update(FieldMap.unit.toDb({ ...this.getUnitById(id), ...patch })).eq('id', id).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ویرایش روی Supabase: ' + error.message, 'error'); return false; }
    const idx = this.cache.units.findIndex(u => u.id === id);
    if (idx > -1) this.cache.units[idx] = FieldMap.unit.fromDb(data);
    this.saveCacheToLocalStorage();
    return true;
  }
  async deleteUnit(id) {
    const { error } = await this.client.from('units').delete().eq('id', id);
    if (error) { console.error(error); Utils.showToast('خطا در حذف روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.units = this.cache.units.filter(u => u.id !== id);
    this.saveCacheToLocalStorage();
    return true;
  }

  /* ------------------ دریافت‌ها ------------------ */
  getReceipts() { return this.cache.receipts; }

  async addReceipt(r) {
    r.docNo = Utils.generateDocNo('RCP', this.cache.receipts);
    const { data, error } = await this.client.from('receipts').insert(FieldMap.receipt.toDb(r)).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ذخیره‌سازی روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.receipts.push(FieldMap.receipt.fromDb(data));
    this.saveCacheToLocalStorage();
    return true;
  }
  async updateReceipt(id, patch) {
    const existing = this.cache.receipts.find(r => r.id === id);
    const { data, error } = await this.client.from('receipts').update(FieldMap.receipt.toDb({ ...existing, ...patch })).eq('id', id).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ویرایش روی Supabase: ' + error.message, 'error'); return false; }
    const idx = this.cache.receipts.findIndex(r => r.id === id);
    if (idx > -1) this.cache.receipts[idx] = FieldMap.receipt.fromDb(data);
    this.saveCacheToLocalStorage();
    return true;
  }
  async deleteReceipt(id) {
    const { error } = await this.client.from('receipts').delete().eq('id', id);
    if (error) { console.error(error); Utils.showToast('خطا در حذف روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.receipts = this.cache.receipts.filter(r => r.id !== id);
    this.saveCacheToLocalStorage();
    return true;
  }

  /* ------------------ هزینه‌ها ------------------ */
  getExpenses() { return this.cache.expenses; }

  async addExpense(e) {
    e.docNo = Utils.generateDocNo('EXP', this.cache.expenses);
    const { data, error } = await this.client.from('expenses').insert(FieldMap.expense.toDb(e)).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ذخیره‌سازی روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.expenses.push(FieldMap.expense.fromDb(data));
    this.saveCacheToLocalStorage();
    return true;
  }
  async updateExpense(id, patch) {
    const existing = this.cache.expenses.find(e => e.id === id);
    const { data, error } = await this.client.from('expenses').update(FieldMap.expense.toDb({ ...existing, ...patch })).eq('id', id).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ویرایش روی Supabase: ' + error.message, 'error'); return false; }
    const idx = this.cache.expenses.findIndex(e => e.id === id);
    if (idx > -1) this.cache.expenses[idx] = FieldMap.expense.fromDb(data);
    this.saveCacheToLocalStorage();
    return true;
  }
  async deleteExpense(id) {
    const { error } = await this.client.from('expenses').delete().eq('id', id);
    if (error) { console.error(error); Utils.showToast('خطا در حذف روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.expenses = this.cache.expenses.filter(e => e.id !== id);
    this.saveCacheToLocalStorage();
    return true;
  }

  /* ------------------ اسناد شارژ ماهانه ------------------ */
  getCharges() { return this.cache.charges; }

  async addCharge(c) {
    c.docNo = Utils.generateDocNo('CHG', this.cache.charges);
    const { data, error } = await this.client.from('charges').insert(FieldMap.charge.toDb(c)).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ذخیره‌سازی روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.charges.push(FieldMap.charge.fromDb(data));
    this.saveCacheToLocalStorage();
    return true;
  }
  async deleteCharge(id) {
    const { error } = await this.client.from('charges').delete().eq('id', id);
    if (error) { console.error(error); Utils.showToast('خطا در حذف روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.charges = this.cache.charges.filter(c => c.id !== id);
    this.saveCacheToLocalStorage();
    return true;
  }
  async deleteChargeBatch(jy, jm) {
    const { error } = await this.client.from('charges').delete().eq('jy', jy).eq('jm', jm);
    if (error) { console.error(error); return false; }
    this.cache.charges = this.cache.charges.filter(c => !(c.jy === jy && c.jm === jm));
    this.saveCacheToLocalStorage();
    return true;
  }
  hasChargeForUnitMonth(unitId, jy, jm) {
    return this.cache.charges.some(c => c.unitId === unitId && c.jy === jy && c.jm === jm);
  }

  /* ------------------ اشخاص ------------------ */
  getPersons() { return this.cache.persons; }
  getPersonById(id) { return this.cache.persons.find(p => p.id === id); }

  async addPerson(p) {
    const { data, error } = await this.client.from('persons').insert(FieldMap.person.toDb(p)).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ذخیره‌سازی روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.persons.push(FieldMap.person.fromDb(data));
    this.saveCacheToLocalStorage();
    return true;
  }
  async updatePerson(id, patch) {
    const existing = this.cache.persons.find(p => p.id === id);
    const { data, error } = await this.client.from('persons').update(FieldMap.person.toDb({ ...existing, ...patch })).eq('id', id).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ویرایش روی Supabase: ' + error.message, 'error'); return false; }
    const idx = this.cache.persons.findIndex(p => p.id === id);
    if (idx > -1) this.cache.persons[idx] = FieldMap.person.fromDb(data);
    this.saveCacheToLocalStorage();
    return true;
  }
  async deletePerson(id) {
    const { error } = await this.client.from('persons').delete().eq('id', id);
    if (error) { console.error(error); Utils.showToast('خطا در حذف روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.persons = this.cache.persons.filter(p => p.id !== id);
    this.saveCacheToLocalStorage();
    return true;
  }

  /* ------------------ تنظیمات ------------------ */
  getSettings() { return this.cache.settings || DEFAULT_SETTINGS; }

  async saveSettings(patch) {
    const merged = { ...this.getSettings(), ...patch };
    const { data, error } = await this.client.from('settings').update(FieldMap.settings.toDb(merged)).eq('id', 1).select().single();
    if (error) { console.error(error); Utils.showToast('خطا در ذخیره تنظیمات روی Supabase: ' + error.message, 'error'); return false; }
    this.cache.settings = FieldMap.settings.fromDb(data);
    this.saveCacheToLocalStorage();
    return true;
  }

  /* ------------------ پشتیبان‌گیری ------------------ */
  exportBackup() {
    const backup = {
      version: 1,
      exportedAt: new Date().toISOString(),
      units: this.getUnits(),
      receipts: this.getReceipts(),
      expenses: this.getExpenses(),
      charges: this.getCharges(),
      persons: this.getPersons(),
      settings: this.getSettings()
    };
    return JSON.stringify(backup, null, 2);
  }

  /** بازیابی کامل: تمام جدول‌های Supabase پاک و با محتوای فایل پشتیبان جایگزین می‌شوند */
  async importBackup(jsonString) {
    try {
      const data = JSON.parse(jsonString);
      if (!data || !Array.isArray(data.units) || !Array.isArray(data.receipts) || !Array.isArray(data.expenses)) {
        throw new Error('ساختار فایل پشتیبان نامعتبر است');
      }
      await this._deleteAllRows();

      const insertedUnits = await this._bulkInsert('units', data.units, FieldMap.unit);
      const insertedPersons = await this._bulkInsert('persons', Array.isArray(data.persons) ? data.persons : [], FieldMap.person);

      // نگاشت شناسه‌های قدیمی به شناسه‌های جدید تولیدشده توسط Supabase برای واحدها/اشخاص
      const unitIdMap = {};
      (data.units || []).forEach((oldUnit, i) => { if (insertedUnits[i]) unitIdMap[oldUnit.id] = insertedUnits[i].id; });
      const personIdMap = {};
      (data.persons || []).forEach((oldPerson, i) => { if (insertedPersons[i]) personIdMap[oldPerson.id] = insertedPersons[i].id; });

      const receiptsToInsert = data.receipts.map(r => ({ ...r, unitId: unitIdMap[r.unitId] || null }));
      const expensesToInsert = data.expenses.map(e => ({ ...e, personId: e.personId ? (personIdMap[e.personId] || null) : null }));
      const chargesToInsert = (Array.isArray(data.charges) ? data.charges : []).map(c => ({ ...c, unitId: unitIdMap[c.unitId] || null })).filter(c => c.unitId);

      await this._bulkInsert('receipts', receiptsToInsert, FieldMap.receipt);
      await this._bulkInsert('expenses', expensesToInsert, FieldMap.expense);
      await this._bulkInsert('charges', chargesToInsert, FieldMap.charge);

      if (data.settings) await this.saveSettings(data.settings);
      await this.init();
      return true;
    } catch (e) {
      console.error('خطا در بازیابی فایل پشتیبان', e);
      return false;
    }
  }

  async _bulkInsert(table, rows, mapper) {
    if (!rows.length) return [];
    const payload = rows.map(mapper.toDb);
    const { data, error } = await this.client.from(table).insert(payload).select();
    if (error) { console.error(`خطا در وارد کردن ${table}`, error); return []; }
    return data || [];
  }

  async _deleteAllRows() {
    await this.client.from('charges').delete().not('id', 'is', null);
    await this.client.from('receipts').delete().not('id', 'is', null);
    await this.client.from('expenses').delete().not('id', 'is', null);
    await this.client.from('units').delete().not('id', 'is', null);
    await this.client.from('persons').delete().not('id', 'is', null);
  }

  /** پاک‌سازی کامل تمام اطلاعات (نگه‌داشتن تنظیمات) */
  async clearAll() {
    await this._deleteAllRows();
    this.cache.units = [];
    this.cache.receipts = [];
    this.cache.expenses = [];
    this.cache.charges = [];
    this.cache.persons = [];
    this.saveCacheToLocalStorage();
  }

  /* ------------------ تم (محلی، مستقل از Supabase) ------------------ */
  getTheme() { return localStorage.getItem('bcm_theme') || 'light'; }
  setTheme(theme) { localStorage.setItem('bcm_theme', theme); }
}

const DB = new StorageManager();

/** استفاده در utils.js برای فرمت ارز */
function Storage_getCurrencyUnit() {
  const s = DB.getSettings();
  return s ? s.currency : 'تومان';
}
